const log = find_block({ names: ["oak_log", "spruce_log", "birch_log", "cherry_log", "dark_oak_log"], max_distance: 24 });
if (!log) {
  const here = position();
  await move_to(here.x + 12, here.y, here.z + 12);
  return { done: false, detail: 'no tree here; walking on' };
}
const chopped = await dig(log.x, log.y, log.z);
if (!chopped.ok) {
  return { done: false, detail: chopped.detail };
}
  const bag = inventory();
  for (const item of bag) {
    await leave_at_depot(item.name, item.count);
  }
return { done: true, detail: 'mined a log and left the bag at the depot' };
